insert into public.blogs (id, title, excerpt, author, author_avatar, category, tags, read_time, publish_date, source_name, url, cover_image, cover_alt, cover_fit, status, featured)
values
('hazyresearch-flashattention-long-sequences', 'FlashAttention: Fast Transformer Training with Long Sequences', 'Tri Dao details how parallelizing FlashAttention over the sequence dimension keeps GPUs saturated at long context, making 8k-token GPT training up to 2.7x faster than an optimized baseline while computing exact attention.', 'Tri Dao', 'https://www.google.com/s2/favicons?domain=hazyresearch.stanford.edu&sz=128', 'Efficient AI', array['FlashAttention','Long Context','GPU Kernels','Training Efficiency'], '9 min read', '2023-01-12', 'Hazy Research', 'https://hazyresearch.stanford.edu/blog/2023-01-12-flashattention-long-sequences', 'assets/img/covers/real/hazyresearch-flashattention-long-sequences.png', 'FlashAttention forward and backward pass parallelization diagram', 'cover', 'published', false),
('hazyresearch-flashattention-2', 'FlashAttention-2: Faster Attention with Better Parallelism and Work Partitioning', 'FlashAttention-2 rewrites the attention kernel with better work partitioning between warps and thread blocks and fewer non-matmul FLOPs, reaching up to 2x the speed of the original FlashAttention and 72% of peak A100 throughput.', 'Tri Dao', 'https://www.google.com/s2/favicons?domain=hazyresearch.stanford.edu&sz=128', 'Efficient AI', array['FlashAttention-2','Attention Kernels','GPU Utilization','Work Partitioning'], '10 min read', '2023-07-17', 'Hazy Research', 'https://hazyresearch.stanford.edu/blog/2023-07-17-flash2', 'assets/img/covers/real/hazyresearch-flashattention-2.png', 'FlashAttention versus FlashAttention-2 work partitioning diagram', 'cover', 'published', false),
('jax-ml-how-to-scale-your-model', 'How to Scale Your Model', 'Google DeepMind engineers turn LLM scaling from alchemy into arithmetic: a book-length treatment of rooflines, TPU and GPU architecture, collective communication, and every major parallelism strategy for training and inference.', 'Jacob Austin, Sholto Douglas, Roy Frostig, et al.', 'https://www.google.com/s2/favicons?domain=jax-ml.github.io&sz=128', 'Efficient AI', array['Systems','Parallelism','Rooflines','TPUs','Scaling'], '90 min read', '2025-02-04', 'Google DeepMind', 'https://jax-ml.github.io/scaling-book/', 'assets/img/covers/real/jax-ml-how-to-scale-your-model.png', 'How to Scale Your Model book cover artwork', 'cover', 'published', false),
('kipply-transformer-inference-arithmetic', 'Transformer Inference Arithmetic', 'Kipply derives a back-of-the-envelope performance model for transformer inference, using KV cache size, weight memory, FLOPs, and communication costs to predict latency and throughput before running a single benchmark.', 'Carol Chen (kipply)', 'https://www.google.com/s2/favicons?domain=kipp.ly&sz=128', 'Efficient AI', array['Inference','KV Cache','Performance Modeling','FLOPs'], '25 min read', '2022-03-30', 'kipply''s blog', 'https://kipp.ly/p/transformer-inference-arithmetic', 'assets/img/covers/real/kipply-transformer-inference-arithmetic.jpg', 'Transformer inference arithmetic article cover', 'cover', 'published', false),
('horace-he-making-deep-learning-go-brrrr', 'Making Deep Learning Go Brrrr From First Principles', 'Horace He splits deep learning performance into compute-bound, memory-bandwidth-bound, and overhead-bound regimes, showing how to diagnose which one you are in and why optimizations like operator fusion only pay off in the right regime.', 'Horace He', 'https://www.google.com/s2/favicons?domain=horace.io&sz=128', 'Efficient AI', array['Performance','Memory Bandwidth','Operator Fusion','Profiling'], '18 min read', '2022-03-15', 'horace.io', 'https://horace.io/brrr_intro.html', 'assets/img/covers/real/horace-he-making-deep-learning-go-brrrr.webp', 'GPUs go brrr illustration from the article', 'cover', 'published', false),
('google-research-gspmd-parallelization', 'General and Scalable Parallelization for Neural Networks', 'Google Research introduces GSPMD, an XLA compiler pass that expands lightweight tensor sharding annotations into full SPMD parallelization, letting a single program express data, model, and pipeline parallelism across thousands of accelerators.', 'Yuanzhong Xu and Yanping Huang', 'https://www.google.com/s2/favicons?domain=research.google&sz=128', 'Efficient AI', array['GSPMD','Model Parallelism','XLA','Distributed Training'], '8 min read', '2021-12-08', 'Google Research', 'https://research.google/blog/general-and-scalable-parallelization-for-neural-networks/', 'assets/img/covers/real/google-research-gspmd-parallelization.jpg', 'GSPMD parallelization article cover', 'cover', 'published', false),
('google-research-looking-back-at-speculative-decoding', 'Looking Back at Speculative Decoding', 'Yaniv Leviathan and colleagues recount the origin of speculative decoding, explaining how draft-then-verify sampling emits several tokens per serial step without changing the output distribution, and how the idea spread through production LLM serving.', 'Yaniv Leviathan, Matan Kalman, and Yossi Matias', 'https://www.google.com/s2/favicons?domain=research.google&sz=128', 'Efficient AI', array['Speculative Decoding','Inference','Latency','LLM Serving'], '9 min read', '2024-12-06', 'Google Research', 'https://research.google/blog/looking-back-at-speculative-decoding/', 'assets/img/covers/real/google-research-looking-back-at-speculative-decoding.jpg', 'Speculative decoding retrospective article cover', 'cover', 'published', false),
('nvidia-mastering-llm-inference-optimization', 'Mastering LLM Techniques: Inference Optimization', 'A single reference that maps the LLM inference stack end to end: prefill versus decode, KV caching, batching, attention variants like MQA/GQA and FlashAttention, PagedAttention, quantization, and model parallelism strategies.', 'Shashank Verma and Neal Vaidya', 'https://www.google.com/s2/favicons?domain=developer.nvidia.com&sz=128', 'Efficient AI', array['Inference Optimization','KV Cache','Attention','Model Parallelism'], '22 min read', '2023-11-17', 'NVIDIA Technical Blog', 'https://developer.nvidia.com/blog/mastering-llm-techniques-inference-optimization/', 'assets/img/covers/real/nvidia-mastering-llm-inference-optimization.png', 'LLM inference optimization overview graphic', 'cover', 'published', false),
('huggingface-peft-parameter-efficient-fine-tuning', 'Parameter-Efficient Fine-Tuning using PEFT', 'Hugging Face introduces the PEFT library, showing how LoRA, prefix tuning, and prompt tuning adapt billion-parameter models by training a small fraction of weights, with checkpoints measured in megabytes instead of tens of gigabytes.', 'Sourab Mangrulkar and Sayak Paul', 'https://www.google.com/s2/favicons?domain=huggingface.co&sz=128', 'Efficient AI', array['PEFT','LoRA','Fine-Tuning','Adapters'], '10 min read', '2023-02-10', 'Hugging Face Blog', 'https://huggingface.co/blog/peft', 'assets/img/covers/real/huggingface-peft-parameter-efficient-fine-tuning.png', 'PEFT library announcement thumbnail', 'cover', 'published', false),
('huggingface-4bit-transformers-bitsandbytes', 'Making LLMs Even More Accessible with bitsandbytes, 4-bit Quantization and QLoRA', 'The QLoRA release explained: 4-bit NF4 quantization, double quantization, and paged optimizers in bitsandbytes let a 65B-parameter model be fine-tuned on a single 48GB GPU while matching 16-bit fine-tuning quality.', 'Younes Belkada, Tim Dettmers, et al.', 'https://www.google.com/s2/favicons?domain=huggingface.co&sz=128', 'Efficient AI', array['Quantization','QLoRA','4-bit','bitsandbytes'], '12 min read', '2023-05-24', 'Hugging Face Blog', 'https://huggingface.co/blog/4bit-transformers-bitsandbytes', 'assets/img/covers/real/huggingface-4bit-transformers-bitsandbytes.png', 'bitsandbytes 4-bit quantization thumbnail', 'cover', 'published', false),
('raschka-lora-and-dora-from-scratch', 'Improving LoRA: Implementing Weight-Decomposed Low-Rank Adaptation (DoRA) from Scratch', 'Sebastian Raschka implements LoRA and DoRA in plain PyTorch from scratch, showing how DoRA''s decomposition of weights into magnitude and direction can beat LoRA even with half the rank.', 'Sebastian Raschka', 'https://www.google.com/s2/favicons?domain=sebastianraschka.com&sz=128', 'Efficient AI', array['LoRA','DoRA','Fine-Tuning','PyTorch'], '16 min read', '2024-02-18', 'Ahead of AI', 'https://magazine.sebastianraschka.com/p/lora-and-dora-from-scratch', 'assets/img/covers/real/raschka-lora-and-dora-from-scratch.jpg', 'LoRA and DoRA from scratch article cover', 'cover', 'published', false),
('epoch-ai-inference-economics-of-language-models', 'Inference Economics of Language Models', 'Ege Erdil builds a first-principles economic model of LLM inference covering arithmetic, memory bandwidth, network bandwidth, and latency constraints, deriving cost-versus-speed Pareto frontiers and why serial speedups get expensive fast.', 'Ege Erdil', 'https://www.google.com/s2/favicons?domain=epoch.ai&sz=128', 'Efficient AI', array['Inference Economics','Serving Cost','Parallelism','Token Latency'], '30 min read', '2025-06-05', 'Epoch AI', 'https://epoch.ai/publications/inference-economics-of-language-models', 'assets/img/covers/real/epoch-ai-inference-economics-of-language-models.png', 'Inference economics of language models report banner', 'cover', 'published', false),
('hazyresearch-thunderkittens-dsl', 'ThunderKittens: A Simple Embedded DSL for AI Kernels', 'Hazy Research argues that GPUs want simple abstractions: ThunderKittens is an embedded CUDA DSL built around 16x16 tiles that makes attention and other AI kernels easier to write while staying competitive with hand-tuned libraries.', 'Benjamin Spector, Aaryan Singhal, Simran Arora, et al.', 'https://www.google.com/s2/favicons?domain=hazyresearch.stanford.edu&sz=128', 'Efficient AI', array['ThunderKittens','CUDA','Kernel DSL','Tensor Cores'], '12 min read', '2024-05-12', 'Hazy Research', 'https://hazyresearch.stanford.edu/blog/2024-05-12-quick-tk', 'assets/img/covers/real/hazyresearch-thunderkittens-dsl.png', 'ThunderKittens blog hero illustration', 'cover', 'published', false),
('uk-aisi-control-red-team-stress-testing-frontier-monitors', 'How Our New Control Red Team is Stress-Testing Frontier Monitors', 'UK AISI''s Control Red Team shares early lessons from red-teaming the internal monitors frontier AI companies use to catch misbehaving models, and lays out the open problems in making those monitors robust to adversarial pressure.', 'UK AI Security Institute', 'https://www.google.com/s2/favicons?domain=aisi.gov.uk&sz=128', 'Trustworthy AI', array['AI Control','Red Teaming','Monitoring','Frontier Safety'], '10 min read', '2026-07-23', 'UK AISI Blog', 'https://www.aisi.gov.uk/blog/how-our-new-control-red-team-is-stress-testing-frontier-monitors', 'assets/img/covers/real/uk-aisi-control-red-team-stress-testing-frontier-monitors.png', 'UK AISI control red team article cover', 'cover', 'published', false),
('redwood-research-prioritizing-threats-for-ai-control', 'Prioritizing Threats for AI Control', 'Ryan Greenblatt maps the space of threats that AI control should defend against, arguing that control resources should be allocated across scheming risk scenarios by likelihood and severity rather than spread evenly over all conceivable failures.', 'Ryan Greenblatt', 'https://www.google.com/s2/favicons?domain=blog.redwoodresearch.org&sz=128', 'Trustworthy AI', array['AI Control','Threat Models','Scheming','Safety Strategy'], '14 min read', '2025-03-19', 'Redwood Research Blog', 'https://blog.redwoodresearch.org/p/prioritizing-threats-for-ai-control', 'assets/img/covers/real/redwood-research-prioritizing-threats-for-ai-control.jpg', 'Prioritizing threats for AI control article cover', 'cover', 'published', false),
('distill-building-blocks-of-interpretability', 'The Building Blocks of Interpretability', 'Olah and colleagues combine feature visualization, attribution, and matrix factorization into composable interfaces for looking inside neural networks, establishing a foundational grammar for modern interpretability tooling.', 'Chris Olah, Arvind Satyanarayan, et al.', 'https://www.google.com/s2/favicons?domain=distill.pub&sz=128', 'Trustworthy AI', array['Interpretability','Feature Visualization','Attribution','Neural Networks'], '25 min read', '2018-03-06', 'Distill', 'https://distill.pub/2018/building-blocks/', 'assets/img/covers/real/distill-building-blocks-of-interpretability.jpg', 'Building blocks of interpretability feature visualization thumbnail', 'cover', 'published', false),
('distill-circuits-thread', 'Thread: Circuits', 'The Distill Circuits thread argues that neural networks contain understandable, reusable circuits of features, documenting curve detectors and other structures weight by weight in InceptionV1 as an ''open science'' interpretability program.', 'Nick Cammarata, Shan Carter, Gabriel Goh, Chris Olah, et al.', 'https://www.google.com/s2/favicons?domain=distill.pub&sz=128', 'Trustworthy AI', array['Circuits','Mechanistic Interpretability','Vision Models','Features'], '60 min read', '2020-03-10', 'Distill', 'https://distill.pub/2020/circuits/', 'assets/img/covers/real/distill-circuits-thread.jpg', 'Distill circuits thread thumbnail', 'cover', 'published', false),
('distill-advex-bugs-discussion', 'A Discussion of ''Adversarial Examples Are Not Bugs, They Are Features''', 'A structured scientific exchange around the claim that adversarial examples exploit non-robust but genuinely predictive features, with six response essays and author replies that sharpen exactly what the result does and does not show.', 'Logan Engstrom, Justin Gilmer, Gabriel Goh, et al.', 'https://www.google.com/s2/favicons?domain=distill.pub&sz=128', 'Trustworthy AI', array['Adversarial Examples','Robustness','Scientific Discussion','Robust Features'], '30 min read', '2019-08-06', 'Distill', 'https://distill.pub/2019/advex-bugs-discussion/', 'assets/img/covers/real/distill-advex-bugs-discussion.jpg', 'Adversarial examples discussion article thumbnail', 'cover', 'published', false),
('deepmind-how-undesired-goals-can-arise-with-correct-rewards', 'How Undesired Goals Can Arise with Correct Rewards', 'DeepMind researchers separate goal misgeneralisation from specification gaming, giving concrete RL and LLM examples where an agent trained with a correct reward signal still learns to pursue the wrong goal out of distribution.', 'Rohin Shah, Victoria Krakovna, Vikrant Varma, and Zachary Kenton', 'https://www.google.com/s2/favicons?domain=deepmind.google&sz=128', 'Trustworthy AI', array['Goal Misgeneralisation','Specification Gaming','Alignment','RL Safety'], '8 min read', '2022-10-07', 'Google DeepMind Blog', 'https://deepmind.google/blog/how-undesired-goals-can-arise-with-correct-rewards/', 'assets/img/covers/real/deepmind-how-undesired-goals-can-arise-with-correct-rewards.webp', 'Goal misgeneralisation article cover', 'cover', 'published', false),
('openai-deliberative-alignment', 'Deliberative Alignment: Reasoning Enables Safer Language Models', 'OpenAI describes deliberative alignment, which teaches o-series models the text of safety specifications and trains them to reason explicitly over those specifications at inference time, improving both refusal precision and jailbreak robustness.', 'OpenAI', 'https://www.google.com/s2/favicons?domain=openai.com&sz=128', 'Trustworthy AI', array['Deliberative Alignment','Safety Training','Reasoning Models','Specifications'], '12 min read', '2024-12-20', 'OpenAI', 'https://openai.com/index/deliberative-alignment/', 'assets/img/covers/real/openai-deliberative-alignment.png', 'Deliberative alignment article cover', 'cover', 'published', false),
('anthropic-simple-probes-can-catch-sleeper-agents', 'Simple Probes Can Catch Sleeper Agents', 'Anthropic shows that simple linear probes on residual-stream activations can detect backdoored ''sleeper agent'' models about to defect, working surprisingly well even with generic contrast prompts unrelated to the backdoor behavior.', 'Anthropic Alignment Science Team', 'https://www.google.com/s2/favicons?domain=anthropic.com&sz=128', 'Trustworthy AI', array['Sleeper Agents','Linear Probes','Defection Detection','Alignment'], '14 min read', '2024-04-23', 'Anthropic Research', 'https://www.anthropic.com/research/probes-catch-sleeper-agents', 'assets/img/covers/real/anthropic-simple-probes-can-catch-sleeper-agents.jpg', 'Sleeper agent probes article cover', 'cover', 'published', false),
('anthropic-off-switch-dual-use-knowledge', 'An Off Switch for Dual-Use Knowledge in AI Models', 'Anthropic and AE Studio introduce GRAM, which routes gradients from dual-use training data into dedicated removable modules, so capabilities like virology knowledge can be deleted at deployment while general abilities stay intact.', 'Anthropic', 'https://www.google.com/s2/favicons?domain=anthropic.com&sz=128', 'Trustworthy AI', array['Dual-Use Knowledge','Gradient Routing','Biosecurity','Safeguards'], '11 min read', '2026-07-08', 'Anthropic Research', 'https://www.anthropic.com/research/off-switch-dual-use', 'assets/img/covers/real/anthropic-off-switch-dual-use-knowledge.png', 'Off switch for dual-use knowledge article cover', 'cover', 'published', false),
('anthropic-diff-tool-behavioral-differences', 'A ''Diff'' Tool for AI: Finding Behavioral Differences in New Models', 'Anthropic Fellows build a diff tool that compares the internal features of two models and flags behaviors exclusive to one of them, surfacing switches like censorship or copyright-refusal features that black-box testing would likely miss.', 'Anthropic', 'https://www.google.com/s2/favicons?domain=anthropic.com&sz=128', 'Trustworthy AI', array['Model Diffing','Interpretability','Auditing','Behavioral Evaluation'], '10 min read', '2026-03-13', 'Anthropic Research', 'https://www.anthropic.com/research/diff-tool', 'assets/img/covers/real/anthropic-diff-tool-behavioral-differences.png', 'Diff tool for AI models article cover', 'cover', 'published', false),
('deepmind-early-warning-system-novel-ai-risks', 'An Early Warning System for Novel AI Risks', 'DeepMind proposes an early-warning framework for frontier risk: evaluate models separately for dangerous capabilities and for alignment, and feed the results into training, deployment, and security decisions before harm can occur.', 'Toby Shevlane', 'https://www.google.com/s2/favicons?domain=deepmind.google&sz=128', 'Trustworthy AI', array['Dangerous Capability Evals','Frontier Risk','Model Evaluation','Governance'], '9 min read', '2023-05-25', 'Google DeepMind Blog', 'https://deepmind.google/blog/an-early-warning-system-for-novel-ai-risks/', 'assets/img/covers/real/deepmind-early-warning-system-novel-ai-risks.webp', 'Early warning system for novel AI risks article cover', 'cover', 'published', false)
